package android.os; import java.util.*; public class Bundle {final Map<String,Object> m=new HashMap<>();public Bundle(){}public Bundle(Bundle b){m.putAll(b.m);}public boolean hasFileDescriptors(){return false;}public Set<String> keySet(){return m.keySet();}public Object get(String k){return m.get(k);}public void putString(String k,String v){m.put(k,v);}public String getString(String k){return (String)m.get(k);}public String getString(String k,String d){return m.containsKey(k)?getString(k):d;}public void putLong(String k,long v){m.put(k,v);}public long getLong(String k){return m.containsKey(k)?(Long)m.get(k):0;}public void putInt(String k,int v){m.put(k,v);}public int getInt(String k){return m.containsKey(k)?(Integer)m.get(k):0;}public void putBoolean(String k,boolean v){m.put(k,v);}public boolean getBoolean(String k){return Boolean.TRUE.equals(m.get(k));}}
